#!/usr/bin/env node
'use strict';
/**
 * Generates `docs/toolchain/contracts/<category>.md` (one per category) plus
 * `docs/toolchain/contracts/README.md` from the category contracts in
 * `packages/development/toolchain/categories/*.yaml` (TRD-2026-8d825f54 TRD-050,
 * PRD REQ-025).
 *
 * Usage:
 *   node scripts/generate-contract-docs.js           write every file
 *   node scripts/generate-contract-docs.js --check   write nothing; exit 1 naming each
 *                                                    missing or stale file, 0 when all match
 *
 * Generated files are never edited by hand: change the category YAML and regenerate.
 * Pure functions are exported for tests; `main()` is guarded by `require.main`.
 */

const fs = require('fs');
const path = require('path');
const yaml = require('js-yaml');
const { classifyCapabilities } = require('../packages/development/lib/toolchain/coverage');

const REPO_ROOT = path.join(__dirname, '..');
const CATEGORIES_DIR = path.join('packages', 'development', 'toolchain', 'categories');
const OUTPUT_DIR = path.join('docs', 'toolchain', 'contracts');
const BUILTIN_DIR = path.join('packages', 'development', 'toolchain', 'builtin');
// Generated runtime mirrors of the source skills: their adapter.yaml copies are not separate backends.
const MIRROR_PACKAGES = new Set(['pi', 'codex', 'opencode', 'full']);
const COVERAGE_HEADING = '## Shipped backends and coverage';

const GENERATED_NOTICE =
  '<!-- Generated by scripts/generate-contract-docs.js from ' +
  'packages/development/toolchain/categories/. Do not edit by hand. -->';

/**
 * Collapse folded/multi-line YAML text to one line and make it safe inside a table cell.
 * Backslashes are doubled before pipes are escaped: otherwise a backslash already in the text
 * pairs with the one added for a following pipe and leaves that pipe splitting the row.
 */
function cell(text) {
  return String(text === undefined || text === null ? '' : text)
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/\\/g, '\\\\')
    .replace(/\|/g, '\\|');
}

function codeList(items) {
  if (!Array.isArray(items) || items.length === 0) return '-';
  return items.map((item) => `\`${cell(item)}\``).join(', ');
}

/**
 * Renders one category contract to Markdown.
 *
 * @param {{category: string, version: string, capabilities: Record<string, object>}} contract
 *   a parsed category contract (see `category-contract-schema.json`)
 * @param {Array<{id: string, coverage: Record<string, string>}>} [backends] shipped backends
 *   for this category with their per-capability coverage; none renders no coverage section
 * @returns {string} the full Markdown document, ending in a single newline
 */
function renderContract(contract, backends = []) {
  const { category, version } = contract;
  const capabilities = contract.capabilities || {};
  const ids = Object.keys(capabilities);
  const requiredIds = ids.filter((id) => capabilities[id].required === true);
  const optionalIds = ids.filter((id) => capabilities[id].required !== true);

  const lines = [];
  lines.push(`# ${category} contract`, '');
  lines.push(GENERATED_NOTICE, '');
  lines.push(`Contract version: \`${version}\``, '');
  lines.push(
    `The \`${category}\` category defines ${ids.length} capabilities: ` +
      `${requiredIds.length} required and ${optionalIds.length} optional. ` +
      'An adapter implementing this category must provide every required capability; ' +
      'a command that needs an optional capability the resolved adapter lacks uses the ' +
      'capability\'s fallback when one is named.',
    ''
  );

  lines.push('## Capabilities', '');
  lines.push('| Capability | Required | Side effect | Inputs | Outputs | Fallback | Added in minor | Description |');
  lines.push('| --- | --- | --- | --- | --- | --- | --- | --- |');
  for (const id of ids) {
    const cap = capabilities[id];
    lines.push(
      `| \`${id}\` | ${cap.required === true ? 'required' : 'optional'} | ` +
        `${cap.sideEffect === true ? 'yes' : 'no'} | ${codeList(cap.inputs)} | ` +
        `${codeList(cap.outputs)} | ${cap.fallback ? `\`${cell(cap.fallback)}\`` : '-'} | ` +
        `${cap.addedInMinor === undefined ? '-' : cap.addedInMinor} | ${cell(cap.description)} |`
    );
  }
  lines.push('');

  if (backends.length > 0) {
    lines.push(COVERAGE_HEADING, '');
    lines.push(
      'One column per shipped backend. `native` = the backend answers the capability itself; ' +
        '`fallback` = the capability is answered by the fallback named in the ' +
        'contract (a builtin analyzer such as work-graph-links-fallback, or a documented degraded path), not by the backend itself; `unavailable` = neither.',
      ''
    );
    lines.push(`| Capability | ${backends.map((b) => b.id).join(' | ')} |`);
    lines.push(`| --- | ${backends.map(() => '---').join(' | ')} |`);
    for (const id of ids) {
      lines.push(`| \`${id}\` | ${backends.map((b) => b.coverage[id] || 'unavailable').join(' | ')} |`);
    }
    lines.push('');
  }

  lines.push('## Details', '');
  for (const id of ids) {
    const cap = capabilities[id];
    lines.push(`### ${id}`, '');
    if (cap.description) lines.push(cell(cap.description).replace(/\\\|/g, '|'), '');
    lines.push(`- Status: ${cap.required === true ? 'required' : 'optional'}`);
    lines.push(`- Side effect: ${cap.sideEffect === true ? 'yes' : 'no'}`);
    lines.push(`- Inputs: ${codeList(cap.inputs)}`);
    lines.push(`- Outputs: ${codeList(cap.outputs)}`);
    lines.push(`- Fallback: ${cap.fallback ? `\`${cell(cap.fallback)}\`` : 'none'}`);
    if (cap.addedInMinor !== undefined) lines.push(`- Added in minor: ${cap.addedInMinor}`);
    lines.push('');
  }

  return `${lines.join('\n').replace(/\n+$/, '')}\n`;
}

/**
 * Renders the index page listing every category with its contract version and counts.
 *
 * @param {Array<{category: string, version: string, capabilities: object}>} contracts
 * @returns {string}
 */
function renderIndex(contracts) {
  const lines = [];
  lines.push('# Toolchain category contracts', '');
  lines.push(GENERATED_NOTICE, '');
  lines.push(
    'Each tool category has a versioned capability contract. Commands and agents call ' +
      'capabilities by id (`<category>.<capability>`); adapters implement them. ' +
      'See the [adapter authoring guide](../../guides/adapter-authoring.md) to write an ' +
      'adapter and the [migration guide](../../guides/toolchain-migration.md) to move ' +
      'hardcoded tool references onto capabilities.',
    ''
  );
  lines.push('| Category | Contract version | Capabilities | Required | Optional |');
  lines.push('| --- | --- | --- | --- | --- |');
  for (const contract of contracts) {
    const caps = Object.values(contract.capabilities || {});
    const required = caps.filter((c) => c.required === true).length;
    lines.push(
      `| [${contract.category}](${contract.category}.md) | \`${contract.version}\` | ` +
        `${caps.length} | ${required} | ${caps.length - required} |`
    );
  }
  lines.push('');
  return lines.join('\n');
}

/**
 * Loads every category contract from `<root>/packages/development/toolchain/categories`,
 * sorted by category name.
 *
 * @param {string} [root]
 * @returns {Array<{category: string, version: string, capabilities: object}>}
 */
function loadCategoryContracts(root = REPO_ROOT) {
  const dir = path.join(root, CATEGORIES_DIR);
  return fs
    .readdirSync(dir)
    .filter((name) => /\.ya?ml$/.test(name))
    .sort()
    .map((name) => yaml.load(fs.readFileSync(path.join(dir, name), 'utf8')))
    .sort((a, b) => a.category.localeCompare(b.category));
}

function readAdapterFiles(root) {
  const files = [];
  const packagesDir = path.join(root, 'packages');
  if (fs.existsSync(packagesDir)) {
    for (const pkg of fs.readdirSync(packagesDir).sort()) {
      if (MIRROR_PACKAGES.has(pkg)) continue;
      const skillsDir = path.join(packagesDir, pkg, 'skills');
      if (!fs.existsSync(skillsDir)) continue;
      for (const skill of fs.readdirSync(skillsDir).sort()) {
        const file = path.join(skillsDir, skill, 'adapter.yaml');
        if (fs.existsSync(file)) files.push(file);
      }
    }
  }
  const builtinDir = path.join(root, BUILTIN_DIR);
  if (fs.existsSync(builtinDir)) {
    for (const name of fs.readdirSync(builtinDir).sort()) {
      const file = path.join(builtinDir, name, 'adapter.yaml');
      if (fs.existsSync(file)) files.push(file);
    }
  }
  return files;
}

/**
 * Shipped backends per category: every non-mirror `packages/*\/skills/*\/adapter.yaml` plus the
 * builtin adapters, deduplicated by adapter id, sorted by id, with per-capability coverage.
 *
 * @param {string} [root]
 * @param {Array<object>} [contracts]
 * @returns {Map<string, Array<{id: string, coverage: Record<string, string>}>>}
 */
function loadShippedBackends(root = REPO_ROOT, contracts = loadCategoryContracts(root)) {
  const builtinIds = fs.existsSync(path.join(root, BUILTIN_DIR))
    ? fs
        .readdirSync(path.join(root, BUILTIN_DIR))
        .filter((n) => fs.existsSync(path.join(root, BUILTIN_DIR, n, 'adapter.yaml')))
    : [];
  const manifests = new Map();
  for (const file of readAdapterFiles(root)) {
    const manifest = yaml.load(fs.readFileSync(file, 'utf8'));
    if (manifest && typeof manifest.adapter === 'string' && !manifests.has(manifest.adapter)) {
      manifests.set(manifest.adapter, manifest);
    }
  }
  const byCategory = new Map();
  for (const contract of contracts) {
    const backends = [];
    for (const [id, manifest] of manifests) {
      if (!Array.isArray(manifest.categories) || !manifest.categories.includes(contract.category)) continue;
      backends.push({ id, coverage: classifyCapabilities(contract, manifest, builtinIds) });
    }
    backends.sort((a, b) => a.id.localeCompare(b.id));
    byCategory.set(contract.category, backends);
  }
  return byCategory;
}

/**
 * The complete expected output set: repo-relative path -> file content.
 *
 * @param {string} [root]
 * @returns {Map<string, string>}
 */
function buildOutputs(root = REPO_ROOT) {
  const contracts = loadCategoryContracts(root);
  const backends = loadShippedBackends(root, contracts);
  const outputs = new Map();
  for (const contract of contracts) {
    outputs.set(
      path.join(OUTPUT_DIR, `${contract.category}.md`),
      renderContract(contract, backends.get(contract.category) || [])
    );
  }
  outputs.set(path.join(OUTPUT_DIR, 'README.md'), renderIndex(contracts));
  return outputs;
}

/**
 * Compares the on-disk docs with regenerated output.
 *
 * @param {string} [root]
 * @returns {string[]} repo-relative paths that are missing or differ
 */
function findStaleFiles(root = REPO_ROOT) {
  const stale = [];
  for (const [rel, content] of buildOutputs(root)) {
    const abs = path.join(root, rel);
    if (!fs.existsSync(abs) || fs.readFileSync(abs, 'utf8') !== content) stale.push(rel);
  }
  return stale;
}

/**
 * Parses the recorded coverage matrix out of a generated doc.
 *
 * @param {string} text
 * @returns {Map<string, Record<string, string>>|null} backend id -> capability -> value, or null
 *   when the doc has no coverage section
 */
function parseRecordedCoverage(text) {
  const start = text.indexOf(COVERAGE_HEADING);
  if (start === -1) return null;
  const rest = text.slice(start + COVERAGE_HEADING.length);
  const end = rest.search(/\n## /);
  const section = end === -1 ? rest : rest.slice(0, end);
  const rows = section
    .split('\n')
    .filter((l) => l.startsWith('|'))
    .map((l) => l.split('|').slice(1, -1).map((c) => c.trim()));
  if (rows.length < 3) return new Map();
  const header = rows[0];
  const recorded = new Map();
  for (const id of header.slice(1)) recorded.set(id, {});
  for (const row of rows.slice(2)) {
    const cap = row[0].replace(/^`|`$/g, '');
    header.slice(1).forEach((id, i) => {
      recorded.get(id)[cap] = row[i + 1];
    });
  }
  return recorded;
}

/**
 * Compares the coverage recorded in the on-disk docs with freshly computed coverage and names
 * every unrecorded change (native-versus-fallback status, newly shipped or removed backend).
 *
 * @param {string} [root]
 * @returns {string[]} human-readable messages, one per unrecorded change
 */
function findCoverageDrift(root = REPO_ROOT) {
  const contracts = loadCategoryContracts(root);
  const fresh = loadShippedBackends(root, contracts);
  const messages = [];
  for (const contract of contracts) {
    const backends = fresh.get(contract.category) || [];
    if (backends.length === 0) continue;
    const rel = path.join(OUTPUT_DIR, `${contract.category}.md`);
    const abs = path.join(root, rel);
    const recorded = fs.existsSync(abs) ? parseRecordedCoverage(fs.readFileSync(abs, 'utf8')) : null;
    for (const backend of backends) {
      const rec = recorded && recorded.get(backend.id);
      if (!rec) {
        messages.push(`adapter '${backend.id}' is shipped but not recorded in ${rel.split(path.sep).join('/')}`);
        continue;
      }
      for (const [cap, now] of Object.entries(backend.coverage)) {
        if (rec[cap] !== now) {
          messages.push(
            `${contract.category}: ${backend.id} ${cap}: recorded ${rec[cap] === undefined ? 'nothing' : rec[cap]}, now ${now}`
          );
        }
      }
    }
    if (recorded) {
      const shipped = new Set(backends.map((b) => b.id));
      for (const id of recorded.keys()) {
        if (!shipped.has(id)) messages.push(`recorded backend '${id}' is no longer shipped`);
      }
    }
  }
  return messages;
}

/**
 * @param {string[]} [argv]
 * @param {string} [root]
 * @returns {number} process exit code
 */
function main(argv = process.argv.slice(2), root = REPO_ROOT) {
  if (argv.includes('--check')) {
    const stale = findStaleFiles(root);
    const drift = findCoverageDrift(root);
    if (stale.length > 0 || drift.length > 0) {
      for (const rel of stale) console.error(`stale or missing: ${rel}`);
      for (const message of drift) console.error(`coverage drift: ${message}`);
      console.error('Run `node scripts/generate-contract-docs.js` to regenerate.');
      return 1;
    }
    console.log('Contract docs are up to date.');
    return 0;
  }

  const outputs = buildOutputs(root);
  fs.mkdirSync(path.join(root, OUTPUT_DIR), { recursive: true });
  for (const [rel, content] of outputs) fs.writeFileSync(path.join(root, rel), content);
  console.log(`Wrote ${outputs.size} contract docs to ${OUTPUT_DIR}.`);
  return 0;
}

module.exports = {
  renderContract,
  renderIndex,
  loadCategoryContracts,
  buildOutputs,
  findStaleFiles,
  findCoverageDrift,
  loadShippedBackends,
  main,
  OUTPUT_DIR
};

if (require.main === module) {
  process.exit(main());
}
